import re

_NUM = r'\d+(?:[.,]\d+)?'
_PATTERN = re.compile(
    r'P(?:'
    rf'({_NUM})W'                      # group 0: weeks alone
    r'|'
    rf'(?:({_NUM})D)?'                 # group 1: days
    rf'(?:T(?=\d)(?:({_NUM})H)?(?:({_NUM})M)?(?:({_NUM})S)?)?'  # groups 2-4: H, M, S
    r')'
)
_MULTIPLIERS = [604800, 86400, 3600, 60, 3600, 60, 1]


def parse_duration(text: str) -> float:
    if not isinstance(text, str):
        raise ValueError("duration must be a string")
    m = _PATTERN.fullmatch(text)
    if m is None:
        raise ValueError(f"invalid ISO 8601 duration: {text!r}")
    groups = m.groups()
    # Map group positions to multipliers: W=0, D=1, H=2, M=3, S=4
    if groups[0] is not None:
        present = [(0, groups[0])]
    else:
        present = [(i, groups[i]) for i in range(1, 5) if groups[i] is not None]
    if not present:
        raise ValueError(f"duration has no components: {text!r}")
    mults = [604800, 86400, 3600, 60, 1]
    total = 0.0
    last = len(present) - 1
    for k, (idx, val) in enumerate(present):
        if k != last and not val.isdigit():
            raise ValueError(f"only the last component may have a fraction: {text!r}")
        total += float(val.replace(',', '.')) * mults[idx]
    return float(total)
